import React from 'react';
import CaseVisual, { isArsenalCase } from './CaseVisual';
import './CaseOpeningSplashUnified.css';

const tone = (name='') => {
  const n=String(name).toLowerCase();
  if(n.includes('rifle')) return '#7f3142';
  if(n.includes('sniper')||n.includes('awp')) return '#2e6688';
  if(n.includes('pistol')) return '#866226';
  if(n.includes('knife')) return '#8e6a2e';
  if(n.includes('glove')) return '#315f78';
  return '#58697a';
};

export default function CaseOpeningSplashUnified({caseData}){
  const accent=tone(caseData?.name);
  return <div className="wc61-splash" style={{'--wc61-accent':accent}} data-splash-version="61" role="dialog" aria-label={`Ouverture de ${caseData?.name||'caisse'}`}>
    <div className="wc61-backdrop"/>
    <div className="wc61-card">
      <div className="wc61-kicker">WELLCASE / OUVERTURE SÉCURISÉE</div>
      <h1>{caseData?.name||'WELLCASE'}</h1>
      <div className="wc61-stage"><CaseVisual caseData={caseData} large splash /></div>
      <div className="wc61-status"><span/>DROP SÉCURISÉ</div>
      <div className="wc61-progress"><i/></div>
    </div>
  </div>;
}
